verification_tests:
from target import setting_from_env


def test_empty_env_value_overrides_fallback():
    assert setting_from_env({"MODE": ""}, "MODE", "default") == ""


def test_zero_env_value_overrides_fallback():
    assert setting_from_env({"PORT": 0}, "PORT", "8080") == 0


def test_missing_env_uses_fallback():
    assert setting_from_env({}, "MODE", "default") == "default"
